    while lst:
        sorted_lst = lst[0]
        for n in range(len(lst)):
            if lst[n] > sorted_lst:
                sorted_lst = lst[n]
        lst.remove(sorted_lst)
        k.append(sorted_lst)
    return k

def top_k(lst, k):
    lst = sort_descending(lst)
    return lst[:k]

